<?php
namespace qqworld_collector\module\collect_filter; class wipe_html_tag_attributes extends filter { public function callback($matches) { return in_array($matches[1], array('img', 'a')) ? $matches[0] : "<{$matches[1]}{$matches[2]}>"; } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if (!empty($args)) { $specified = isset($args['specified']) ? $args['specified'] : ''; $all = isset($args['all']) ? filter_var($args['all'], FILTER_VALIDATE_BOOLEAN) : 0; if ($all) { $item = preg_replace_callback("/<([a-z][a-z0-9]*)[^>]*?(\/?)>/i", array($this, 'callback'), $item); } elseif ($specified) { $patterns = array(); $replacements = array(); $attributes = explode("\r\n", $specified); foreach ($attributes as $attribute) { $attribute = str_replace('*', '[^"]*?', $attribute); $patterns[] = '/ '.$attribute.'="[^"]*?"/i'; $replacements[] = ''; $patterns[] = '/ '.$attribute.'=\'[^\']*?\'/i'; $replacements[] = ''; } $item = preg_replace($patterns, $replacements, $item); } } return $item; } } ?>